// Demo: Spring Design Calculator - public implementations survey
(function(){'use strict';
var DATA={"label": "Spring Design Calculator - public implementations survey", "items": [{"name": "GD&T", "qty": 8, "unit": 17.34}, {"name": "Machinery's Handbook", "qty": 2, "unit": 442.36}, {"name": "SKF bearings", "qty": 4, "unit": 420.51}, {"name": "FMEA", "qty": 2, "unit": 486.85}], "contingency": 10};

